  Material.WireFrameFillMode = 1;
  Material.PointFillMode = 2;
  Material.PointListDrawMode = 3;
  Material.LineListDrawMode = 4;
  Material.LineLoopDrawMode = 5;
  Material.LineStripDrawMode = 6;
  Material.ClockWiseSideOrientation = 0;
  Material.CounterClockWiseSideOrientation = 1;

  class StandardMaterial extends Material {
    constructor(name, scene) {
      super(name, scene);
      this.diffuseColor = new Color3(1, 1, 1);
      this.ambientColor = new Color3(0.2, 0.2, 0.24);
      this.emissiveColor = new Color3(0, 0, 0);
      this.specularColor = new Color3(0.18, 0.18, 0.18);
      this.specularPower = 32;
      this.diffuseTexture = null;
      this.emissiveTexture = null;
      this.bumpTexture = null;
      this.useAlphaFromDiffuseTexture = false;
      this.linkEmissiveWithDiffuse = false;
      this.disableLighting = false;
      this.roughness = 0.5;
    }
  }

  class PBRMaterial extends StandardMaterial {
    constructor(name, scene) {
      super(name, scene);
      this.albedoColor = this.diffuseColor;
      this.metallic = 0.1;
      this.roughness = 0.5;
      this.indexOfRefraction = 1.31;
      this.emissiveIntensity = 1.0;
      this.environmentIntensity = 1.0;
      this.clearCoat = { isEnabled: false, intensity: 1.0, roughness: 0.08 };
    }
    get albedoTexture() { return this.diffuseTexture; }
    set albedoTexture(v) { this.diffuseTexture = v; }
  }
