  Texture.WRAP_ADDRESSMODE = 1;
  Texture.TRILINEAR_SAMPLINGMODE = 3;
  Texture.BILINEAR_SAMPLINGMODE = 2;
  Texture.CUBIC_MODE = 3;

  class DynamicTexture extends Texture {
    constructor(name, options, scene, generateMipMaps = true) {
      super(name, scene);
      this._generateMipMaps = generateMipMaps;
      if (options && typeof options.getContext === 'function') {
        this._canvas = options;
      } else {
        const w = typeof options === 'number' ? options : (options && options.width) || 256;
        const h = typeof options === 'number' ? options : (options && options.height) || 256;
        this._canvas = document.createElement('canvas');
        this._canvas.width = w;
        this._canvas.height = h;
      }
      this._ctx = this._canvas.getContext('2d');
      this._dirty = true;
    }
    getContext() {
      return this._ctx;
    }
    update(invertY = true) {
      this._invertY = invertY;
      this._dirty = true;
    }
  }

  class Layer {
    constructor(name, imgUrl, scene, isBackground = true, color) {
      this.name = name;
      this.texture = null;
      this.isBackground = isBackground;
      this.color = color || new Color4(1, 1, 1, 1);
      this._scene = scene || Engine._activeScene;
      if (this._scene) {
        this._scene.layers.push(this);
      }
    }
  }

  class Light extends Node {
    constructor(name, scene) {
      super(name, scene);
      this.diffuse = new Color3(1, 1, 1);
      this.specular = new Color3(0.25, 0.25, 0.25);
      this.intensity = 1.0;
      this.range = 100;
      if (this._scene && this._scene.lights) {
        this._scene.lights.push(this);
      }
    }
  }
